class GlyphEngine final : public QIconEngine {
public:
    explicit GlyphEngine(const QString& glyph) : m_glyph(glyph) {}
    QIconEngine* clone() const override { return new GlyphEngine(m_glyph); }
    QPixmap pixmap(const QSize& size, QIcon::Mode mode, QIcon::State) override {
        QPixmap pm(size);
        pm.fill(Qt::transparent);
        fluent::FontIcon renderer(m_glyph);
        renderer.setIconSize(qMin(size.width(), size.height()));
        renderer.setEnabled(mode != QIcon::Disabled);
        renderer.resize(size);
        QPainter painter(&pm);
        renderer.render(&painter, QPoint(), QRegion(), QWidget::DrawChildren);
        return pm;
    }
    void paint(QPainter* painter, const QRect& rect, QIcon::Mode mode, QIcon::State state) override {
        const int dpr = painter->device() ? qMax(1, qRound(painter->device()->devicePixelRatioF())) : 1;
        painter->drawPixmap(rect, pixmap(rect.size() * dpr, mode, state));
    }
private:
    QString m_glyph;
};
auto* rootLayout = new QVBoxLayout(%PARENT%);
rootLayout->setContentsMargins(0, 0, 0, 0);
auto* control = new fluent::navigation::NavigationView(%PARENT%);
rootLayout->addWidget(control);
control->setDisplayMode(fluent::navigation::NavigationView::DisplayMode::Left);
control->setExpandedPaneWidth(168);
auto* header = new QWidget(control);
auto* headerLayout = new QHBoxLayout(header);
headerLayout->setContentsMargins(4, 4, 4, 4);
headerLayout->setSpacing(6);
auto* toggle = new fluent::basicinput::Button(header);
toggle->setIconGlyph(Typography::Icons::GlobalNav);
toggle->setFluentLayout(fluent::basicinput::Button::IconOnly);
toggle->setFluentStyle(fluent::basicinput::Button::Subtle);
toggle->setAccessibleName(QStringLiteral("Toggle navigation pane"));
toggle->setFixedSize(36, 32);
auto* brand = new fluent::textfields::Label(QStringLiteral("Workspace"), header);
brand->setFluentTypography(Typography::FontRole::BodyStrong);
headerLayout->addWidget(toggle);
headerLayout->addWidget(brand, 1);
control->setHeaderChromeWidget(header);
QObject::connect(toggle, &fluent::basicinput::Button::clicked, control, [control] {
    control->setPaneOpen(!control->isPaneOpen());
});
auto* navList = new fluent::collections::ListView(control);
navList->setFrameShape(QFrame::NoFrame);
navList->setBackgroundVisible(false);
navList->setBorderVisible(false);
navList->setIconSize(QSize(16, 16));
auto* navModel = new QStandardItemModel(navList);
struct NavEntry {
    QString title;
    QString glyph;
    QString summary;
    QString detail;
};
const QVector<NavEntry> entries{
    {QStringLiteral("Home"), Typography::Icons::Home, QStringLiteral("Pinned projects & status"), QStringLiteral("Jump back to active Fluent component kits and recent workspace changes.")},
    {QStringLiteral("Explore"), Typography::Icons::Search, QStringLiteral("Design kits & templates"), QStringLiteral("Browse adaptive layouts, typography tokens, and starter pages.")},
    {QStringLiteral("Settings"), Typography::Icons::Settings, QStringLiteral("Appearance & behavior"), QStringLiteral("Adjust Light/Dark tokens, pane density, and navigation chrome modes.")},
};
for (const auto& entry : entries) {
    auto* item = new QStandardItem(QIcon(new GlyphEngine(entry.glyph)), entry.title);
    item->setToolTip(entry.title);
    navModel->appendRow(item);
}
navList->setModel(navModel);
control->setMainChromeWidget(navList);
QList<fluent::basicinput::Button*> minimalToggles;
for (int row = 0; row < entries.size(); ++row) {
    const auto& entry = entries.at(row);
    auto* page = new QWidget(control->contentHost());
    auto* pageLayout = new QVBoxLayout(page);
    pageLayout->setContentsMargins(16, 14, 16, 14);
    pageLayout->setSpacing(10);
    auto* topRow = new QHBoxLayout;
    topRow->setContentsMargins(0, 0, 0, 0);
    topRow->setSpacing(8);
    auto* minToggle = new fluent::basicinput::Button(page);
    minToggle->setIconGlyph(Typography::Icons::GlobalNav);
    minToggle->setFluentLayout(fluent::basicinput::Button::IconOnly);
    minToggle->setFluentStyle(fluent::basicinput::Button::Subtle);
    minToggle->setAccessibleName(QStringLiteral("Open navigation menu"));
    minToggle->setFixedSize(32, 28);
    QObject::connect(minToggle, &fluent::basicinput::Button::clicked, control, [control] { control->setPaneOpen(true); });
    minimalToggles.append(minToggle);
    auto* title = new fluent::textfields::Label(entry.title, page);
    title->setFluentTypography(Typography::FontRole::Subtitle);
    topRow->addWidget(minToggle);
    topRow->addWidget(title, 1);
    pageLayout->addLayout(topRow);
    auto* card = new fluent::layout::Card(page);
    auto* cardLayout = new QVBoxLayout(card);
    cardLayout->setContentsMargins(14, 12, 14, 12);
    cardLayout->setSpacing(4);
    auto* cardTitle = new fluent::textfields::Label(entry.summary, card);
    cardTitle->setFluentTypography(Typography::FontRole::BodyStrong);
    auto* cardBody = new fluent::textfields::Label(entry.detail, card);
    cardBody->setFluentTypography(Typography::FontRole::Caption);
    cardBody->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
    cardBody->setWordWrap(true);
    cardLayout->addWidget(cardTitle);
    cardLayout->addWidget(cardBody);
    pageLayout->addWidget(card);
    pageLayout->addStretch(1);
    control->contentHost()->insertPage(row, page);
}
const auto syncChrome = [control, headerLayout, toggle, brand, navList, navModel, minimalToggles] {
    const auto mode = control->effectiveDisplayMode();
    const bool open = control->isPaneOpen();
    const bool top = mode == fluent::navigation::NavigationView::DisplayMode::Top;
    const bool compactClosed = (mode == fluent::navigation::NavigationView::DisplayMode::Left || mode == fluent::navigation::NavigationView::DisplayMode::LeftCompact) && !open;
    const bool minimalClosed = mode == fluent::navigation::NavigationView::DisplayMode::LeftMinimal && !open;
    const int compactMargin = qMax(2, (control->compactPaneWidth() - toggle->minimumWidth()) / 2);
    headerLayout->setContentsMargins(top ? 12 : (compactClosed ? compactMargin : 4), 4, 4, 4);
    toggle->setVisible(!top);
    brand->setVisible(!compactClosed);
    navList->setFlow(top ? QListView::LeftToRight : QListView::TopToBottom);
    navList->setWrapping(false);
    navList->setHorizontalScrollBarPolicy(Qt::ScrollBarAlwaysOff);
    navList->setVerticalScrollBarPolicy(top ? Qt::ScrollBarAlwaysOff : Qt::ScrollBarAsNeeded);
    if (top) {
        navList->setFixedHeight(control->topBarHeight());
        navList->setFixedWidth(368);
    } else {
        navList->setMinimumSize(0, 0);
        navList->setMaximumSize(16777215, 16777215);
    }
    const int topItemHeight = qBound(34, control->topBarHeight() - 6, 44);
    for (int i = 0; i < navModel->rowCount(); ++i) {
        if (auto* item = navModel->item(i))
            item->setData(top ? QVariant(QSize(88, topItemHeight)) : QVariant(), Qt::SizeHintRole);
    }
    for (auto* btn : minimalToggles)
        btn->setVisible(minimalClosed);
};
QObject::connect(control, &fluent::navigation::NavigationView::displayModeChanged, control, [syncChrome](fluent::navigation::NavigationView::DisplayMode) { syncChrome(); });
QObject::connect(control, &fluent::navigation::NavigationView::effectiveDisplayModeChanged, control, [syncChrome](fluent::navigation::NavigationView::DisplayMode) { syncChrome(); });
QObject::connect(control, &fluent::navigation::NavigationView::paneOpenChanged, control, [syncChrome](bool) { syncChrome(); });
QObject::connect(control, &fluent::navigation::NavigationView::compactPaneWidthChanged, control, [syncChrome](int) { syncChrome(); });
QObject::connect(control, &fluent::navigation::NavigationView::topBarHeightChanged, control, [syncChrome](int) { syncChrome(); });
QObject::connect(navList->selectionModel(), &QItemSelectionModel::currentChanged, control, [control](const QModelIndex& index) {
    control->contentHost()->setCurrentIndex(index.row(), 0, false);
});
syncChrome();
navList->setCurrentIndex(navModel->index(0, 0));
